    "(SELECT COUNT(*) FROM orders o WHERE o.CustomerId = c.Id AND " + PAID + ") AS Orders, "
    "(SELECT COALESCE(SUM(o.TotalCents), 0) FROM orders o WHERE o.CustomerId = c.Id AND " + PAID + ") AS SpentCents, "
