def detail_sql(where):
    return (
        "SELECT o.*, "
        "(SELECT json_group_array(json_object('Id', i.Id, 'ProductId', i.ProductId, 'VariantId', i.VariantId, 'Sku', i.Sku, 'Title', i.Title, "
